{
  "root": "main",
  "state": {
    "diagnosticSteps": [
      {
        "step": "1",
        "action": "Check power cable",
        "expected": "Indicator light turns on"
      },
      {
        "step": "2",
        "action": "Verify network connection",
        "expected": "Stable link status"
      },
      {
        "step": "3",
        "action": "Restart system",
        "expected": "System boots to dashboard"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "description",
        "diagnosticTable",
        "divider",
        "supportActions",
        "contactButton",
        "faqButton",
        "footer"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "System Troubleshooting Guide",
        "variant": "h1"
      },
      "children": []
    },
    "description": {
      "type": "Text",
      "props": {
        "text": "Follow these steps to resolve common connectivity and power issues.",
        "variant": "body"
      },
      "children": []
    },
    "diagnosticTable": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "step",
            "label": "Step"
          },
          {
            "key": "action",
            "label": "Action"
          },
          {
            "key": "expected",
            "label": "Expected Result"
          }
        ],
        "statePath": "/diagnosticSteps",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "step",
        "highlightColumns": [
          "action"
        ]
      },
      "children": []
    },
    "divider": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "supportActions": {
      "type": "Text",
      "props": {
        "text": "Need further assistance?",
        "variant": "h3"
      },
      "children": []
    },
    "contactButton": {
      "type": "Button",
      "props": {
        "label": "Contact Support",
        "on": {
          "press": {
            "action": "openUrl",
            "params": {
              "url": "https://support.example.com"
            }
          }
        }
      },
      "children": []
    },
    "faqButton": {
      "type": "Button",
      "props": {
        "label": "View FAQ",
        "on": {
          "press": {
            "action": "openUrl",
            "params": {
              "url": "https://faq.example.com"
            }
          }
        }
      },
      "children": []
    },
    "footer": {
      "type": "Text",
      "props": {
        "text": "Last updated: 2023-10-27",
        "variant": "caption"
      },
      "children": []
    }
  }
}
